# Static xrefs for the correction round. Read-only.
# Descriptor counts, pose-variable references, and calls into the orientation
# getter and the ten-byte producer. Do not edit this file after it has run.
import json
from pathlib import Path

BASE = 0x60021020
img = Path('inputs/00_0100_50000020.decoded.bin').read_bytes()
n = len(img)
TABLES = [0x60095584, 0x600b8f54, 0x600bb5ec, 0x600bda78, 0x600e4bec]
KEYS = {
    0x5962: '5962', 0x88B2: '88b2', 0x1DD1: '1dd1', 0x1DB1: '1db1', 0x1DC1: '1dc1',
    0x99A1: '99a1', 0x9A41: '9a41', 0x99D2: '99d2', 0xDFA1: 'dfa1', 0xE91: 'e91',
    0x90A1: '90a1', 0x84D1: '84d1', 0x1DF1: '1df1', 0x1E01: '1e01', 0x5991: '5991',
    0xE1F1: 'e1f1',
}
CALLS = {
    0x60077DE1: 'exif-get',
    0x60077E01: 'raw-get',
    0x609B3ECD: 'converter',
    0x609B3C79: 'refresh-claimed',
    0x609B3DFB: 'triple-reader',
    0x609B3BB2: 'accessor-claimed',
    0x60903E55: 'ten-copy',
    0x609B3481: 'context',
    0x60063380: 'settings-get',
}
ABS = {
    0xA32C568C: 'pose-index',
    0xA32C5690: 'pose-raw',
    0xA32C5688: 'pose-flag',
    0xA33AC4E2: 'exif-cache',
    0xA33F2CE0: 'capture-record',
    0xA33CA384: 'consumer-record',
    0xA33F2CEA: 'dirty',
}
REFRESH_LO = 0x609B3C00
REFRESH_HI = 0x609B3D70


def u16(off):
    return img[off] | (img[off + 1] << 8)


def s32(off):
    v = int.from_bytes(img[off:off + 4], 'little')
    return v - 0x100000000 if v & 0x80000000 else v


def s16(off):
    v = u16(off)
    return v - 0x10000 if v & 0x8000 else v


lines = []
def w(s=''):
    lines.append(s)


w('scan-xrefs-r1')
w(f'image bytes {n}')

found = {}
w('')
w('## registration records')
for start in TABLES:
    a = start
    count_rows = 0
    while count_rows < 5000:
        off = a - BASE
        if off < 0 or off + 4 > n:
            w(f'table 0x{start:08x} walked off the image at 0x{a:08x}')
            break
        key = u16(off)
        if key == 0:
            w(f'table 0x{start:08x} records {count_rows} zero-key at 0x{a:08x}')
            break
        count = u16(off + 2)
        width = (key & 3) or 4
        payload = 4 + count * width
        if key in KEYS:
            raw = img[off + 4:off + 4 + count * width]
            row = {
                'key': key, 'name': KEYS[key], 'table': start, 'record': a,
                'count': count, 'width': width, 'header': img[off:off + 4].hex(),
                'payload': raw.hex(),
            }
            found[f'{key:04x}'] = row
            w(f"key 0x{key:04x} {KEYS[key]} table 0x{start:08x} record 0x{a:08x} count {count} width {width} header {row['header']} payload {row['payload']}")
        nxt = (a + payload + 3) & ~3
        if nxt <= a:
            w(f'table 0x{start:08x} did not advance at 0x{a:08x}')
            break
        a = nxt
        count_rows += 1
    else:
        w(f'table 0x{start:08x} unbounded')

missing = [name for key, name in KEYS.items() if f'{key:04x}' not in found]
w('missing ' + (' '.join(missing) if missing else 'none'))

hits = {name: [] for name in CALLS.values()}
hits['refresh-range'] = []
abs_hits = {name: [] for name in ABS.values()}
i = 0
while i < n - 6:
    op = img[i]
    pc = BASE + i
    target = None
    if op == 0xDD and i + 7 <= n:
        target = (pc + s32(i + 1)) & 0xFFFFFFFF
    elif op == 0xCD and i + 5 <= n:
        target = (pc + s16(i + 1)) & 0xFFFFFFFF
    elif op == 0xDC and i + 5 <= n:
        target = (pc + s32(i + 1)) & 0xFFFFFFFF
    elif op == 0xCC and i + 3 <= n:
        target = (pc + s16(i + 1)) & 0xFFFFFFFF
    name = CALLS.get(target)
    if name and len(hits[name]) < 80:
        hits[name].append(pc)
    if target is not None and REFRESH_LO <= target < REFRESH_HI and len(hits['refresh-range']) < 40:
        hits['refresh-range'].append((pc, target))
    if op == 0xFC and i + 6 <= n:
        abs_addr = int.from_bytes(img[i + 2:i + 6], 'little')
        aname = ABS.get(abs_addr)
        if aname and len(abs_hits[aname]) < 60:
            abs_hits[aname].append(pc)
    i += 1

w('')
w('## calls')
for name, pcs in hits.items():
    if name == 'settings-get':
        w(f'{name} calls {len(pcs)} (capped)')
        continue
    if name == 'refresh-range':
        shown = ' '.join(f'{pc:08x}-> {tgt:08x}' for pc, tgt in pcs)
        w(f'{name} {len(pcs)} {shown}')
        continue
    shown = ' '.join(f'{pc:08x}' for pc in pcs)
    w(f'{name} calls {len(pcs)} {shown}')

w('')
w('## absolute operands')
for name, pcs in abs_hits.items():
    shown = ' '.join(f'{pc:08x}' for pc in pcs)
    w(f'{name} {len(pcs)} {shown}')

# Bytes after each EXIF and raw getter call, so the following immediates are visible.
w('')
w('## bytes after orientation getter calls')
for name in ('exif-get', 'raw-get'):
    for pc in hits[name]:
        off = pc - BASE
        window = img[off:off + 48]
        w(f'{name} {pc:08x} {window.hex()}')

text = '\n'.join(lines) + '\n'
Path('work/out/scan-xrefs-r1.txt').write_text(text, encoding='utf-8')
Path('work/out/descriptors-r1.json').write_text(json.dumps(found, indent=2) + '\n', encoding='utf-8')
print(text)
